const els = Object.fromEntries([
  'setupScreen','handoffScreen','cardScreen','starterScreen','endScreen',
  'countOutput','namesArea','imposterOptions','formError','currentPlayerName',
  'roundNumber','progressFill','progressText','secretCard','cardBack',
  'roleBadge','secretWord','secretHint','cardInstruction','cardCounter',
  'flipStatus','starterSlot','starterResult','startGameBtn','endStarter','musicBtn'
].map(id=>[id,document.getElementById(id)]));

let count=4, imposterCount=1;
let game={
  players:[], round:0, order:[], position:0, secret:'', hint:'',
  imposters:[], recentSecrets:[], recentImposters:[], previousStarter:null,
  starter:null, musicOn:false, audio:null, musicTimer:null
};

const shuffle = arr => {
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}
  return a;
};
const optionsFor = n => n<=5?[1]:n<=7?[1,2]:[1,2,3];

function show(id){
  ['setupScreen','handoffScreen','cardScreen','starterScreen','endScreen']
    .forEach(k=>els[k].classList.toggle('hidden',k!==id));
  window.scrollTo({top:0,behavior:'instant'});
}

function renderSetup(){
  els.countOutput.textContent=count;
  els.namesArea.innerHTML=Array.from({length:count},(_,i)=>
    `<input class="name-input" aria-label="Player ${i+1} name" placeholder="Player ${i+1} name" value="${escapeHtml(game.players[i]||'')}">`
  ).join('');
  const valid=optionsFor(count);
  if(!valid.includes(imposterCount)) imposterCount=valid[0];
  els.imposterOptions.innerHTML=valid.map(n=>
    `<button type="button" class="imposter-option ${n===imposterCount?'selected':''}" data-number="${n}" role="radio" aria-checked="${n===imposterCount}">${n} IMPOSTER${n>1?'S':''}</button>`
  ).join('');
  els.imposterOptions.querySelectorAll('button').forEach(btn=>btn.onclick=()=>{
    imposterCount=Number(btn.dataset.number);
    renderSetup();
  });
}

function escapeHtml(value){
  return String(value).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
}

function saveNames(){
  game.players=[...document.querySelectorAll('.name-input')].map(i=>i.value.trim());
}

els.countOutput.addEventListener('change',()=>{});
document.getElementById('minusBtn').onclick=()=>{if(count>2){saveNames();count--;renderSetup()}};
document.getElementById('plusBtn').onclick=()=>{if(count<10){saveNames();count++;renderSetup()}};

document.getElementById('setupForm').onsubmit=e=>{
  e.preventDefault(); saveNames();
  if(game.players.some(n=>!n)){els.formError.textContent='Please enter a name for everyone.';return}
  const lower=game.players.map(n=>n.toLowerCase());
  if(new Set(lower).size!==lower.length){els.formError.textContent='Give duplicate names a nickname so the pass is clear.';return}
  els.formError.textContent='';
  game.round=0; game.recentSecrets=[]; game.recentImposters=[]; game.previousStarter=null;
  startRound();
};

function chooseImposters(){
  const all=game.players.map((_,i)=>i);
  let pool=all.filter(i=>!game.recentImposters.includes(i));
  if(pool.length<imposterCount) pool=all;
  return shuffle(pool).slice(0,imposterCount);
}

function chooseSecret(){
  let available=secretBank.filter(([word])=>!game.recentSecrets.includes(word));
  if(!available.length) available=secretBank;
  const pick=available[Math.floor(Math.random()*available.length)];
  game.recentSecrets=[...game.recentSecrets,pick[0]].slice(-12);
  return pick;
}

function startRound(){
  game.round++;
  const [secret,hint]=chooseSecret();
  game.secret=secret; game.hint=hint;
  game.imposters=chooseImposters();
  game.order=shuffle(game.players.map((_,i)=>i));
  game.position=0; game.starter=null;
  els.roundNumber.textContent=game.round;
  show('handoffScreen'); showHandoff();
  if(game.musicOn) startMusic();
}

function showHandoff(){
  const idx=game.order[game.position];
  els.currentPlayerName.textContent=game.players[idx];
  els.progressFill.style.width=`${(game.position/game.players.length)*100}%`;
  els.progressText.textContent=`PLAYER ${game.position+1} OF ${game.players.length}`;
}

function prepareCard(){
  const idx=game.order[game.position];
  const isImposter=game.imposters.includes(idx);
  els.roleBadge.textContent=isImposter?'🚨 YOU ARE THE IMPOSTER':'🔵 YOUR SECRET';
  els.secretWord.textContent=isImposter?'':game.secret;
  els.secretHint.textContent=isImposter ? game.hint : '';
  els.cardBack.classList.toggle('imposter', isImposter);
  els.cardBack.classList.toggle('normal-player', !isImposter);
  els.cardInstruction.textContent=isImposter?'Blend in. Tap again to hide your role.':'Tap again to hide your secret.';
  els.cardCounter.textContent=`PLAYER ${game.position+1} OF ${game.players.length}`;
  els.secretCard.classList.remove('flipped');
  els.flipStatus.textContent='Tap the card to reveal your secret.';
  show('cardScreen');
}

document.getElementById('readyBtn').onclick=prepareCard;

function revealOrCloseCard(){
  if(!els.secretCard.classList.contains('flipped')){
    els.secretCard.classList.add('flipped');
    els.flipStatus.textContent='Tap the card again to hide it and pass the phone.';
    els.secretCard.setAttribute('aria-label','Tap to hide your secret and pass the phone');
  }else{
    els.secretCard.classList.remove('flipped');
    els.flipStatus.textContent='Hidden. Passing to the next player…';
    els.secretCard.setAttribute('aria-label','Secret hidden');
    window.setTimeout(nextPlayer,760);
  }
}
els.secretCard.onclick=revealOrCloseCard;
els.secretCard.onkeydown=e=>{
  if(e.key==='Enter'||e.key===' '){
    e.preventDefault();
    revealOrCloseCard();
  }
};

function nextPlayer(){
  game.position++;
  if(game.position>=game.players.length) beginStarter();
  else { show('handoffScreen'); showHandoff(); }
}

/* Starter selection: random each round, but never the previous round's starter. */
function beginStarter(){
  show('starterScreen');
  els.starterSlot.classList.add('rolling');
  els.starterResult.classList.add('hidden');
  els.startGameBtn.classList.add('hidden');

  let pool=game.players.map((_,i)=>i);
  if(game.previousStarter!==null && pool.length>1) pool=pool.filter(i=>i!==game.previousStarter);
  const chosen=pool[Math.floor(Math.random()*pool.length)];
  let ticks=0, duration=1850;
  const timer=setInterval(()=>{
    const temp=pool[Math.floor(Math.random()*pool.length)];
    els.starterSlot.textContent=game.players[temp].toUpperCase();
    ticks++;
    if(ticks*80>=duration){
      clearInterval(timer);
      game.starter=chosen;
      game.previousStarter=chosen;
      els.starterSlot.classList.remove('rolling');
      els.starterSlot.textContent=game.players[chosen].toUpperCase();
      els.starterResult.classList.remove('hidden');
      els.startGameBtn.classList.remove('hidden');
    }
  },80);
}

els.startGameBtn.onclick=()=>{
  els.endStarter.textContent=`${game.players[game.starter]} starts the round.`;
  show('endScreen');
};

els.newRoundBtn?.addEventListener('click',()=>startRound());
document.getElementById('newRoundBtn').onclick=()=>startRound();
document.getElementById('newGameBtn').onclick=()=>{
  game={players:[],round:0,order:[],position:0,secret:'',hint:'',imposters:[],recentSecrets:[],recentImposters:[],previousStarter:null,starter:null,musicOn:game.musicOn,audio:game.audio,musicTimer:game.musicTimer};
  count=4; imposterCount=1; renderSetup(); show('setupScreen');
};

function startMusic(){
  if(!game.audio){
    const C=window.AudioContext||window.webkitAudioContext;
    if(!C) return;
    game.audio=new C();
  }
  if(game.audio.state==='suspended') game.audio.resume();
  if(game.musicTimer) return;
  const notes=[261.63,329.63,392,523.25,392,329.63,293.66,440];
  let i=0;
  game.musicTimer=setInterval(()=>{
    const o=game.audio.createOscillator(),g=game.audio.createGain();
    o.type='triangle'; o.frequency.value=notes[i++%notes.length];
    g.gain.setValueAtTime(.0001,game.audio.currentTime);
    g.gain.exponentialRampToValueAtTime(.018,game.audio.currentTime+.02);
    g.gain.exponentialRampToValueAtTime(.0001,game.audio.currentTime+.24);
    o.connect(g).connect(game.audio.destination); o.start(); o.stop(game.audio.currentTime+.26);
  },360);
}
function stopMusic(){
  clearInterval(game.musicTimer); game.musicTimer=null;
}
els.musicBtn.onclick=()=>{
  game.musicOn=!game.musicOn;
  els.musicBtn.setAttribute('aria-pressed',game.musicOn);
  els.musicBtn.textContent=game.musicOn?'♪ MUSIC ON':'♪ MUSIC OFF';
  game.musicOn?startMusic():stopMusic();
};

renderSetup();
